sealed trait Cmd
final case class Put(msg: Message, replyTo: ActorRef[Done]) extends Cmd
final case class Get(replyTo: ActorRef[Option[Message]]) extends Cmd
def apply(): Behavior[Cmd] = Behaviors.setup { _ =>
  var queue = Vector.empty[Message]                // servant state, confined
  Behaviors.receiveMessage {
    case Put(m, replyTo) => queue :+= m; replyTo ! Done; Behaviors.same
    case Get(replyTo)    => replyTo ! queue.headOption; Behaviors.same
  }
}
// caller: ref.ask(Get(_))                             // returns Future[Option[Message]]

