private val scheduler =
  ExecutionContext.fromExecutor(Executors.newSingleThreadExecutor())

class ActiveQueue(servant: MQServant) {
  def put(m: Message): Future[Unit] = Future(servant.putI(m))(scheduler)
  def get(): Future[Message]        = Future(servant.getI())(scheduler)
}
